public sealed class LabExtractionSafetyTests
{
    [Fact]
    public async Task ExtractAsync_WhenRecognizedRowsAreZero_FailsWithoutWritingValuesOrFlags()
    {
        var options = new DbContextOptionsBuilder<AppDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).Options;
        await using var db = new AppDbContext(options);
        var user = new UserAccount { Email = "synthetic-zero-rows@example.invalid", PasswordHash = "synthetic", DisplayName = "Synthetic User", UserType = UserType.FamilyUser };
        var family = new Family { Name = "Synthetic Zero Rows Family", CreatedByUser = user };
        var member = new Member { Family = family, User = user, DisplayName = "Synthetic Member", DateOfBirth = new DateOnly(1990, 1, 1), Role = FamilyRole.Head };
        var report = new LabReport { Member = member, OriginalFileName = "synthetic-zero.png", StoredFileName = "db:synthetic.png", ContentType = "image/png", SizeBytes = 100, OcrStatus = OcrStatus.Pending };
        db.AddRange(user, family, member, report);
        await db.SaveChangesAsync();
        var dispatcher = new ZeroRowsDispatcher();
        var service = new LabExtractionService(db, new StubCurrentUser(user.Id), [new ExtractionAgent(dispatcher)]);

        await service.Invoking(x => x.ExtractAsync(report.Id, CancellationToken.None)).Should().ThrowAsync<ProcessingException>();

        dispatcher.WriteCalls.Should().Be(0);
        (await db.LabValues.CountAsync()).Should().Be(0);
        (await db.HereditaryFlags.CountAsync()).Should().Be(0);
        var failed = await db.LabReports.SingleAsync(x => x.Id == report.Id);
        failed.OcrStatus.Should().Be(OcrStatus.Failed);
        failed.OcrErrorCode.Should().Be(OcrFailureCodes.NoValuesFound);
    }

    [Theory]
    [InlineData(10, true)]
    [InlineData(1, false)]
    public async Task ExtractAsync_RetriesOnlyReadsStuckInProcessingPastTheStaleWindow(int minutesAgo, bool retried)
    {
        var options = new DbContextOptionsBuilder<AppDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).Options;
        await using var db = new AppDbContext(options);
        var user = new UserAccount { Email = "synthetic-stale@example.invalid", PasswordHash = "synthetic", DisplayName = "Synthetic User", UserType = UserType.FamilyUser };
        var family = new Family { Name = "Synthetic Stale Family", CreatedByUser = user };
        var member = new Member { Family = family, User = user, DisplayName = "Synthetic Member", DateOfBirth = new DateOnly(1990, 1, 1), Role = FamilyRole.Head };
        var report = new LabReport { Member = member, OriginalFileName = "synthetic-stale.png", StoredFileName = "db:synthetic.png", ContentType = "image/png", SizeBytes = 100, OcrStatus = OcrStatus.Processing };
        db.AddRange(user, family, member, report);
        await db.SaveChangesAsync();
        // A restart cut the read off: the row was last touched before the stale window.
        report.UpdatedAt = DateTimeOffset.UtcNow.AddMinutes(-minutesAgo);
        var agent = new StubExtractionAgent();
        var service = new LabExtractionService(db, new StubCurrentUser(user.Id), [agent]);

        var extraction = () => service.ExtractAsync(report.Id, CancellationToken.None);

        if (retried) (await extraction()).Status.Should().Be(OcrStatus.Completed);
        else await extraction.Should().ThrowAsync<ConflictException>();
        agent.CallCount.Should().Be(retried ? 1 : 0);
    }

    [Fact]
    public async Task ExtractAsync_WhenReportContainsManuallyConfirmedData_RejectsAndPreservesConfirmedRows()
    {
        var options = new DbContextOptionsBuilder<AppDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).Options;
        await using var db = new AppDbContext(options);
        var user = new UserAccount { Email = "synthetic-reextract@example.invalid", PasswordHash = "synthetic", DisplayName = "Synthetic User", UserType = UserType.FamilyUser };
        var family = new Family { Name = "Synthetic Re-extraction Family", CreatedByUser = user };
        var member = new Member { Family = family, User = user, DisplayName = "Synthetic Member", DateOfBirth = new DateOnly(1990, 1, 1), Role = FamilyRole.Head };
        var report = new LabReport { Member = member, OriginalFileName = "synthetic-confirmed.pdf", StoredFileName = "synthetic-confirmed.pdf", ContentType = "application/pdf", SizeBytes = 100, OcrStatus = OcrStatus.Completed };
        var value = new LabValue { LabReport = report, Analyte = "Confirmed Synthetic Analyte", Value = 7m, Unit = "unit", ReferenceLow = 1m, ReferenceHigh = 9m, WasManuallyConfirmed = true };
        var flag = new HereditaryFlag { Member = member, LabReport = report, ConditionCode = "SYNTHETIC_CONFIRMED_FLAG", Finding = "Synthetic screening signal", Confidence = 0.8m, ManuallyConfirmed = true };
        db.AddRange(user, family, member, report, value, flag);
        await db.SaveChangesAsync();
        var agent = new StubExtractionAgent();
        var service = new LabExtractionService(db, new StubCurrentUser(user.Id), [agent]);

        var extraction = () => service.ExtractAsync(report.Id, CancellationToken.None);

        await extraction.Should().ThrowAsync<ConflictException>();
        agent.CallCount.Should().Be(0);
        db.ChangeTracker.Clear();
        var preservedValue = await db.LabValues.SingleAsync(x => x.Id == value.Id);
        preservedValue.Analyte.Should().Be("Confirmed Synthetic Analyte");
        preservedValue.Value.Should().Be(7m);
        preservedValue.WasManuallyConfirmed.Should().BeTrue();
        var preservedFlag = await db.HereditaryFlags.SingleAsync(x => x.Id == flag.Id);
        preservedFlag.ConditionCode.Should().Be("SYNTHETIC_CONFIRMED_FLAG");
        preservedFlag.ManuallyConfirmed.Should().BeTrue();
    }

    [Fact]
    public async Task ExtractAsync_WhenOnlyHereditaryFlagIsManuallyConfirmed_RejectsBeforeAgentRuns()
    {
        var options = new DbContextOptionsBuilder<AppDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).Options;
        await using var db = new AppDbContext(options);
        var user = new UserAccount { Email = "synthetic-flag-reextract@example.invalid", PasswordHash = "synthetic", DisplayName = "Synthetic User", UserType = UserType.FamilyUser };
        var family = new Family { Name = "Synthetic Flag Re-extraction Family", CreatedByUser = user };
        var member = new Member { Family = family, User = user, DisplayName = "Synthetic Member", DateOfBirth = new DateOnly(1990, 1, 1), Role = FamilyRole.Head };
        var report = new LabReport { Member = member, OriginalFileName = "synthetic-confirmed-flag.pdf", StoredFileName = "synthetic-confirmed-flag.pdf", ContentType = "application/pdf", SizeBytes = 100, OcrStatus = OcrStatus.Completed };
        var value = new LabValue { LabReport = report, Analyte = "Unconfirmed Synthetic Analyte", Value = 4m, Unit = "unit", WasManuallyConfirmed = false };
        var flag = new HereditaryFlag { Member = member, LabReport = report, ConditionCode = "SYNTHETIC_CONFIRMED_FLAG_ONLY", Finding = "Synthetic screening signal", Confidence = 0.7m, ManuallyConfirmed = true };
        db.AddRange(user, family, member, report, value, flag);
        await db.SaveChangesAsync();
        var agent = new StubExtractionAgent();
        var service = new LabExtractionService(db, new StubCurrentUser(user.Id), [agent]);

        var extraction = () => service.ExtractAsync(report.Id, CancellationToken.None);

        await extraction.Should().ThrowAsync<ConflictException>();
        agent.CallCount.Should().Be(0);
        (await db.LabValues.SingleAsync(x => x.Id == value.Id)).Analyte.Should().Be("Unconfirmed Synthetic Analyte");
        (await db.HereditaryFlags.SingleAsync(x => x.Id == flag.Id)).ManuallyConfirmed.Should().BeTrue();
    }

    [Fact]
    public async Task ExtractAsync_WhenClientDisconnectsMidRead_StillCompletes()
    {
        var (db, user, report) = await SeedPendingReportAsync("synthetic-disconnect");
        await using var _ = db;
        using var request = new CancellationTokenSource();
        var agent = new SlowExtractionAgent(onStart: request.Cancel, delay: TimeSpan.FromMilliseconds(200));
        var service = new LabExtractionService(db, new StubCurrentUser(user.Id), [agent]);

        var result = await service.ExtractAsync(report.Id, request.Token);

        request.IsCancellationRequested.Should().BeTrue();
        agent.SawCancellation.Should().BeFalse();
        result.Status.Should().Be(OcrStatus.Completed);
        var stored = await db.LabReports.SingleAsync(x => x.Id == report.Id);
        stored.OcrStatus.Should().Be(OcrStatus.Completed);
        stored.OcrErrorCode.Should().BeNull();
    }

    [Fact]
    public async Task ExtractAsync_WhenServerTimeoutElapses_FailsWithOcrTimeout()
    {
        var (db, user, report) = await SeedPendingReportAsync("synthetic-timeout");
        await using var _ = db;
        var agent = new SlowExtractionAgent(onStart: () => { }, delay: Timeout.InfiniteTimeSpan);
        var service = new LabExtractionService(db, new StubCurrentUser(user.Id), [agent]) { OcrTimeout = TimeSpan.FromMilliseconds(100) };

        var failure = await service.Invoking(x => x.ExtractAsync(report.Id, CancellationToken.None)).Should().ThrowAsync<ProcessingException>();

        failure.Which.Code.Should().Be(OcrFailureCodes.TimedOut);
        var stored = await db.LabReports.SingleAsync(x => x.Id == report.Id);
        stored.OcrStatus.Should().Be(OcrStatus.Failed);
        stored.OcrErrorCode.Should().Be(OcrFailureCodes.TimedOut);
    }

    [Theory]
    [InlineData(null, 150)]
    [InlineData("1", 10)]
    [InlineData("45", 45)]
    [InlineData("9999", 600)]
    public void OcrTimeout_ReadsAndClampsConfiguration(string? configured, int expectedSeconds)
    {
        var configuration = new ConfigurationBuilder()
            .AddInMemoryCollection(new Dictionary<string, string?> { ["Ocr:TotalTimeoutSeconds"] = configured }).Build();
        var service = new LabExtractionService(null!, new StubCurrentUser(Guid.NewGuid()), [], configuration);

        service.OcrTimeout.Should().Be(TimeSpan.FromSeconds(expectedSeconds));
    }

    private static async Task<(AppDbContext Db, UserAccount User, LabReport Report)> SeedPendingReportAsync(string tag)
    {
        var options = new DbContextOptionsBuilder<AppDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).Options;
        var db = new AppDbContext(options);
        var user = new UserAccount { Email = $"{tag}@example.invalid", PasswordHash = "synthetic", DisplayName = "Synthetic User", UserType = UserType.FamilyUser };
        var family = new Family { Name = "Synthetic Family", CreatedByUser = user };
        var member = new Member { Family = family, User = user, DisplayName = "Synthetic Member", DateOfBirth = new DateOnly(1990, 1, 1), Role = FamilyRole.Head };
        var report = new LabReport { Member = member, OriginalFileName = $"{tag}.png", StoredFileName = "db:synthetic.png", ContentType = "image/png", SizeBytes = 100, OcrStatus = OcrStatus.Pending };
        db.AddRange(user, family, member, report);
        await db.SaveChangesAsync();
        return (db, user, report);
    }

    private sealed class SlowExtractionAgent(Action onStart, TimeSpan delay) : IAgent
    {
        public AgentKind Kind => AgentKind.Extraction;
        public bool SawCancellation { get; private set; }

        public async Task<AgentRunResult> RunAsync(AgentRunContext context, CancellationToken cancellationToken)
        {
            onStart();
            try { await Task.Delay(delay, cancellationToken); }
            catch (OperationCanceledException) { SawCancellation = true; throw; }
            return new AgentRunResult(Kind, "{\"valuesExtracted\":1,\"flagsExtracted\":0}", 1m, [], [], [], true);
        }
    }

    private sealed class StubExtractionAgent : IAgent
    {
        public AgentKind Kind => AgentKind.Extraction;
        public int CallCount { get; private set; }

        public Task<AgentRunResult> RunAsync(AgentRunContext context, CancellationToken cancellationToken)
        {
            CallCount++;
            return Task.FromResult(new AgentRunResult(
                Kind,
                "{\"valuesExtracted\":0,\"flagsExtracted\":0}",
                1m,
                [],
                [],
                [],
                true));
        }
    }

    private sealed class ZeroRowsDispatcher : IToolDispatcher
    {
        public int WriteCalls { get; private set; }

        public Task<object> InvokeAsync(AgentKind agent, string tool, Guid memberId, Guid caseId, CancellationToken cancellationToken, object? arguments = null)
        {
            if (tool == "ocr_extract") return Task.FromResult<object>("unheaded prose only");
            if (tool == "write_lab_extraction") WriteCalls++;
            return Task.FromResult<object>(new object());
        }
    }

    private sealed class StubCurrentUser(Guid userId) : ICurrentUser
    {
        public bool IsAuthenticated => true;
        public Guid UserId => userId;
        public UserType UserType => UserType.FamilyUser;
    }
}
